package vn.svframe.svframelib.api.crafting.recipes; import net.minecraft.item.ItemStack; import java.util.*; import java.util.concurrent.ConcurrentHashMap; public class SVFrameCraftingManager { public static final ItemStack AIR=ItemStack.EMPTY; private static final Map<String,SVFrameRecipe> LOADED=new ConcurrentHashMap<>(); private static final Map<String,ArrayList<SVFrameRecipeBlueprint>> STATIONS=new ConcurrentHashMap<>(); public static void log(String s){System.getLogger("SVFrameLib-Crafting").log(System.Logger.Level.INFO,s);} public static SVFrameRecipe getLoadedRecipe(String id){return LOADED.get(id);} public static ArrayList<String> getLoadedRecipes(){return new ArrayList<>(LOADED.keySet());} public static void load(SVFrameRecipe r){LOADED.put(r.getName(),r);r.load();} public static void deployBlueprint(SVFrameRecipeBlueprint b,SVFrameRecipeStation s){deployBlueprint(b,s,"");} public static void deployBlueprint(SVFrameRecipeBlueprint b,SVFrameRecipeStation s,String key){STATIONS.computeIfAbsent(s.name()+":"+(key==null?"":key.toLowerCase(Locale.ROOT)),k->new ArrayList<>()).add(b);} public static ArrayList<SVFrameRecipeBlueprint> getStationRecipes(SVFrameRecipeStation s,String key){return new ArrayList<>(STATIONS.getOrDefault(s.name()+":"+(key==null?"":key.toLowerCase(Locale.ROOT)),new ArrayList<>()));} static void removeBlueprint(SVFrameRecipeBlueprint b){STATIONS.values().forEach(list->list.remove(b));} public static void clear(){STATIONS.clear();LOADED.clear();} }
